import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;
public class App extends Application {
@Override
public void start(Stage stage) {
Label label = new Label("Count: 0");
Button btn = new Button("+1");
int[] count = { 0 };
btn.setOnAction(e -> {
count[0]++;
label.setText("Count: " + count[0]);
});
VBox root = new VBox(10, label, btn);
root.setStyle("-fx-padding: 20;");
stage.setScene(new Scene(root, 200, 120));
stage.setTitle("Counter");
stage.show();
}
public static void main(String[] args) { launch(args); }
}

Style with CSS — JavaFX uses a CSS variant where selectors look like normal CSS but properties are prefixed with -fx-:
.button { -fx-background-color: #4080ff; -fx-text-fill: white; -fx-padding: 6 12; }
.button:hover { -fx-background-color: #3070ee; }
Attach with scene.getStylesheets().add(getClass().getResource("/style.css").toExternalForm());.

For non-trivial apps, define the UI in FXML (an XML markup), edit visually in Scene Builder, wire to a controller class via @FXML.
<!-- counter.fxml -->
<VBox xmlns:fx="http://javafx.com/fxml" fx:controller="com.example.CounterController" spacing="10">
<Label fx:id="label" text="Count: 0"/>
<Button fx:id="btn" text="+1" onAction="#onInc"/>
</VBox>
public class CounterController {
@FXML private Label label;
private int count = 0;
@FXML private void onInc() { label.setText("Count: " + (++count)); }
}

